with deduped as (select *, row_number() over (partition by customer_id order by start_date nulls last, id) as latest_rank from subscriptions qualify latest_rank = 1) select s.id, s.customer_id, s.start_date, s.monthly_fee, s.latest_rank, (select max(a2.balance) from accounts a2 where a2.customer_id = s.customer_id) as max_account_balance from deduped s order by customer_id nulls last
